input.content:
/* Pink vellum envelope: pure CSS, driven by custom properties.
   Toggle .is-open on .envelope to open/close. */

.envelope {
  --env-w: min(86vw, 560px);
  --pink: 244, 128, 170;
  --pink-light: 252, 176, 205;
  --pink-deep: 226, 84, 138;
  --card: #f4efe4;
  --ink: #26211f;
  --ease: cubic-bezier(.5, .1, .2, 1);

  position: relative;
  width: var(--env-w);
  aspect-ratio: 8 / 5;
  perspective: 1400px;
  transform: rotate(-3deg);
  filter: drop-shadow(0 1.2em 1.4em rgba(150, 60, 100, .22));
  container-type: inline-size;
}

/* The back of the envelope body, visible behind the card */
.env-back {
  position: absolute;
  inset: 0;
  border-radius: 1.2cqw;
  background: linear-gradient(160deg, rgba(var(--pink), .95), rgba(var(--pink-deep), .95));
}

/* Flap: a triangle hinged on the top edge */
.flap {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 56%;
  transform-origin: top center;
  transform: rotateX(180deg);
  transition: transform .9s var(--ease), z-index 0s .45s;
  clip-path: polygon(0 0, 100% 0, 50% 100%);
  background: linear-gradient(180deg, rgba(var(--pink-light), .92), rgba(var(--pink), .88));
  z-index: 1;
}

/* Card tucked inside, tilted like the reference */
.card {
  position: absolute;
  left: 11%;
  bottom: 12%;
  width: 78%;
  aspect-ratio: 7 / 5;
  background:
    radial-gradient(120% 90% at 20% 10%, rgba(255, 255, 255, .55), transparent 60%),
    var(--card);
  box-shadow: 0 .3em .9em rgba(120, 50, 80, .18);
  transform-origin: 50% 80%;
  transform: translate(-6%, -42%) rotate(24deg);
  transition: transform 1s var(--ease) .25s;
  z-index: 2;
  container-type: inline-size;
  color: var(--ink);
  font-family: "Work Sans", sans-serif;
}

/* Front pocket: translucent, so the card ghosts through */
.env-front {
  position: absolute;
  inset: 0;
  z-index: 3;
  border-radius: 1.2cqw;
  clip-path: polygon(0 0, 50% 54%, 100% 0, 100% 100%, 0 100%);
  background: linear-gradient(180deg, rgba(var(--pink), .62), rgba(var(--pink-deep), .7));
  -webkit-backdrop-filter: blur(1.5px);
  backdrop-filter: blur(1.5px);
}

/* Bottom fold overlaps the side folds, so the layers read darker */
.env-front::before,
.env-front::after {
  content: "";
  position: absolute;
  inset: 0;
}
.env-front::before {
  clip-path: polygon(0 100%, 50% 46%, 100% 100%);
  background: linear-gradient(180deg, rgba(var(--pink-light), .5), rgba(var(--pink-deep), .35));
  mix-blend-mode: multiply;
}
.env-front::after {
  clip-path: polygon(0 0, 50% 54%, 0 100%, 100% 100%, 50% 54%, 100% 0, 100% 100%, 0 100%);
  background: linear-gradient(90deg, rgba(var(--pink-deep), .22), transparent 30%, transparent 70%, rgba(var(--pink-deep), .22));
  mix-blend-mode: multiply;
}

/* Closed state */
.envelope:not(.is-open) .flap {
  transform: rotateX(0);
  z-index: 4;
  transition: transform .9s var(--ease) .25s, z-index 0s .25s;
}
.envelope:not(.is-open) .card {
  transform: translateY(8%) rotate(0);
  transition-delay: 0s;
}

/* Placeholder card content (swap for the real letter later) */
.card-text {
  position: absolute;
  inset: 0;
  padding: 7cqw 8cqw;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 2cqw;
  text-align: center;
}
.card-eyebrow {
  font-size: 4cqw;
  font-weight: 600;
  letter-spacing: .18em;
  text-transform: uppercase;
}
.card-title {
  font-family: "Pinyon Script", cursive;
  font-size: 19cqw;
  line-height: .95;
}
.card-sub {
  font-family: "Pinyon Script", cursive;
  font-size: 8cqw;
  color: rgb(var(--pink-deep));
}

