/* Blue vellum envelope (portrait): pure CSS, all geometry in % of the envelope
   so --ratio can change the proportions without touching anything else. */

.envelope-blue {
  --env-w: min(80vw, 520px);
  --ratio: 0.81; /* width / height; reference is ~0.81 */
  --blue: 104, 130, 214;
  --blue-light: 150, 172, 232;
  --card: #fbf6de;
  --ink: #1d1b19;
  --awning: #5a1c16;
  --sky: #b9c6dc;
  --photo: none; /* swap in a real image: url(...) */
  --ease: cubic-bezier(.5, .1, .2, 1);

  position: relative;
  width: var(--env-w);
  aspect-ratio: var(--ratio);
  container-type: inline-size;
  filter: drop-shadow(0 1.4em 1.6em rgba(70, 80, 130, .22));
  transition: aspect-ratio .5s var(--ease);
}

.envelope-blue > * {
  position: absolute;
}

/* Back panel, rounded at the top like the reference */
.eb-back {
  inset: 0;
  border-radius: 3cqw 3cqw .6cqw .6cqw;
  background: linear-gradient(180deg, rgba(var(--blue-light), .9), rgba(var(--blue), .95) 40%);
}

/* Postcard peeking out behind the note */
.eb-postcard {
  left: -.7%;
  top: -11.5%;
  width: 69%;
  height: 80%;
  transform: rotate(-.8deg);
  transition: transform .9s var(--ease);
  background:
    var(--photo) center / cover,
    linear-gradient(180deg, transparent 36%, #9bb0c9 36%, #b7c5d8 52%, #4f6b3d 56%, #355a2c 72%, #2d5a6e 78%, #2a4a63);
  background-color: var(--sky);
  box-shadow: 0 .4em 1em rgba(40, 40, 60, .2);
}
.eb-postcard::before { /* awning */
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 22%;
  background: var(--awning);
}
.eb-postcard::after { /* awning scallops */
  content: "";
  position: absolute;
  top: 22%;
  left: 0;
  right: 0;
  height: 9cqw;
  background: radial-gradient(circle at 50% 0, var(--awning) 6.2cqw, transparent 6.5cqw) 0 0 / 16cqw 9cqw repeat-x;
}

/* Note card */
.eb-note {
  left: 30%;
  top: 17%;
  width: 69%;
  height: 78%;
  transform: rotate(1.2deg);
  transition: transform .9s var(--ease) .1s;
  background:
    radial-gradient(130% 80% at 30% 0, rgba(255, 255, 255, .6), transparent 65%),
    var(--card);
  box-shadow: 0 .3em .8em rgba(40, 50, 90, .18);
  color: var(--ink);
  font-family: "Space Grotesk", sans-serif;
}
.eb-note p {
  position: absolute;
  top: 7%;
  left: 0;
  right: 0;
  text-align: center;
  font-size: 3.4cqw;
  font-weight: 500;
}
.eb-note::after { /* embossed seal near the bottom */
  content: "";
  position: absolute;
  bottom: 4.5%;
  left: 50%;
  width: 11%;
  aspect-ratio: 5 / 3;
  transform: translateX(-50%);
  border: .35cqw solid rgba(255, 255, 255, .85);
  border-radius: 50%;
  box-shadow: inset 0 0 0 .7cqw rgba(255, 255, 255, .0), 0 0 .3cqw rgba(90, 100, 160, .35);
}

/* Lifted state: pull the note and postcard up and out */
.envelope-blue.is-lifted .eb-note { transform: translateY(-22%) rotate(1.2deg); }
.envelope-blue.is-lifted .eb-postcard { transform: translateY(-9%) rotate(-.8deg); }

/* Vellum folds: translucent, overlapping, so overlaps read darker */
.eb-left,
.eb-right,
.eb-bottom {
  z-index: 3;
  background: linear-gradient(180deg, rgba(var(--blue-light), .62), rgba(var(--blue), .72));
  -webkit-backdrop-filter: blur(1px);
  backdrop-filter: blur(1px);
}
.eb-left {
  left: 0;
  top: 0;
  width: 27%;
  height: 100%;
  clip-path: polygon(0 42%, 100% 55%, 100% 100%, 0 100%);
}
.eb-right {
  left: 78%;
  top: 0;
  width: 22%;
  height: 100%;
  clip-path: polygon(0 53%, 100% 42%, 100% 100%, 0 100%);
}
.eb-bottom {
  left: 6.5%;
  top: 58%;
  width: 88%;
  height: 42%;
  border-radius: 2.5cqw 2.5cqw .6cqw .6cqw;
  background: linear-gradient(180deg, rgba(var(--blue-light), .55), rgba(var(--blue), .68));
  box-shadow: inset 0 .15cqw 0 rgba(255, 255, 255, .25);
}

