import re
# ---------- HTML ----------
p='envelope-blue-preview.html'
s=open(p).read()

s=s.replace("family=Space+Grotesk:wght@400;500&","family=Instrument+Serif:ital@0;1&")
assert "Instrument+Serif" in s

# wrapper: a <button> can't contain links, so use a plain div
s=re.sub(r'<button class="envelope-toggle"[^>]*>','<div class="envelope-toggle">',s)
s=s.replace('</button>\n      <!-- <div class="controls"','</div>\n      <!-- <div class="controls"',1)

note='''<div class="eb-note">
            <div class="eb-note-body">
              <p>Hello world, I'm Ashley Kang! I use my caboodle of research, design, code, and AI to make more room for people to do things that feel like play 🪄</p>
              <p>My career mixtape is about learning from the best: A season in web development with an award-winning in-house marketing team and a design + technology consulting collective, then a pivot to cybersecurity on world-class teams such as an applied AI unicorn, now a side quest advising marketing agency and social impact nonprofit clients on how to use AI with intention for day-to-day operations and bold product visions. I have a MS in computer science and a BA in a self-designed liberal arts concentration in art, media studies, and computer science.</p>
              <p>I'm open to learning about project collaborations and full-time opportunities where I get to use my product mind, security heart, and builder hands. My idea of a good time is scrolling <a href="https://www.apartmenttherapy.com/" target="_blank">Apartment Therapy</a> while sipping an einspänner or discovering local gems where princesses like my friends and I can hide from our duties.</p>
              <p>Elsewhere:</p>
              <ul>
                <li><a href="https://linkedin.com/in/kangashley" target="_blank">LinkedIn</a></li>
                <li>Member @ <a href="https://www.jointheogc.com/" target="_blank">the old girls club</a>, <a href="https://aisnackclub.com/" target="_blank">AI Snack Club</a>, <a href="https://www.wicys.org/" target="_blank">Women in CyberSecurity</a></li>
                <li>Speaker @ <a href="https://web.archive.org/web/20251012155320/https://www.tuftswit.com/speakers" target="_blank">Tufts Women in Tech Conference</a>, <a href="https://www.instagram.com/buwics/p/DQpDy3HDg78/" target="_blank">BU Women in Computer Science Club</a></li>
              </ul>
              <p class="note">Credits: Designed and developed by yours truly (&#169; 2026 Ashley Kang), layout help from Claude Code and SuperHi, typeset with Jacquard 24 and Work Sans from Google Fonts, compressed with Squoosh</p>
            </div>
          </div>'''
s,n=re.subn(r'<div class="eb-note">.*?</div>',note,s,count=1,flags=re.S)
assert n==1

# start lifted so more of the note is readable above the bottom fold
s=s.replace('<div class="envelope-blue">','<div class="envelope-blue is-lifted">')

# script: keep the lift toggle (ignoring link clicks), comment out the ratio switcher
script='''<script>
      const env = document.querySelector('.envelope-blue');
      document.querySelector('.envelope-toggle').addEventListener('click', (e) => {
        if (e.target.closest('a')) return;
        env.classList.toggle('is-lifted');
      });
      /* Ratio switcher (preview only, controls are commented out above)
      const ratios = document.querySelectorAll('[data-ratio]');
      ratios.forEach(b => b.addEventListener('click', () => {
        env.style.setProperty('--ratio', b.dataset.ratio);
        ratios.forEach(o => o.setAttribute('aria-pressed', o === b));
      }));
      */
    </script>'''
s=re.sub(r'<script>.*?</script>',script,s,flags=re.S)
open(p,'w').write(s)

# ---------- CSS ----------
p='css/envelope-blue.css'
c=open(p).read()
c=c.replace("  --awning: #5a1c16;\n  --sky: #b9c6dc;\n  --photo: none; /* swap in a real image: url(...) */\n","  --photo: url(../media/folio-etc-beach.jpg);\n")
# postcard: real photo, drop awning placeholder
c=re.sub(r"  background:\n    var\(--photo\) center / cover,.*?background-color: var\(--sky\);\n","  background: var(--photo) center / cover;\n",c,flags=re.S)
c=re.sub(r"\.eb-postcard::before \{.*?\n\}\n\.eb-postcard::after \{.*?\n\}\n","",c,flags=re.S)
# note text
c=c.replace('font-family: "Space Grotesk", sans-serif;','font-family: "Instrument Serif", serif;')
c=re.sub(r"\.eb-note p \{.*?\n\}\n",""".eb-note {
  overflow: hidden;
}
.eb-note-body {
  position: absolute;
  inset: 0;
  padding: 5.5cqw 6cqw 14cqw;
  overflow-y: auto;
  scrollbar-width: none;
  font-size: max(14px, 3.3cqw);
  line-height: 1.25;
}
.eb-note-body::-webkit-scrollbar { display: none; }
.eb-note-body p + p,
.eb-note-body ul { margin-top: .7em; }
.eb-note-body ul { padding-left: 1.1em; list-style: disc; }
.eb-note-body li + li { margin-top: .3em; }
.eb-note-body a { color: inherit; text-decoration: underline; text-underline-offset: .12em; }
.eb-note-body .note { font-size: .8em; opacity: .65; }
""",c,count=1,flags=re.S)
# folds shouldn't block scrolling/links in the note
c=c.replace(".eb-left,\n.eb-right,\n.eb-bottom {\n  z-index: 3;",".eb-left,\n.eb-right,\n.eb-bottom {\n  z-index: 3;\n  pointer-events: none;")
open(p,'w').write(c)
EOF
