input.command:
S=/private/tmp/claude-501/-Users-ashleykang-Desktop-kangashley-github-io/c40360be-d0dc-42fb-87bd-043ce6738cdd/scratchpad && cp index.html $S/index.before-header-move.html && cp css/style.css $S/style.before-header-move.css && python3 - <<'EOF'
import re
p='index.html'
s=open(p).read()
m=re.search(r'              <header class="letterhead">
(.*?)              </header>
',s,re.S)
assert m
inner=m.group(1)
s=s.replace(m.group(0),'',1)
new='            <header class="letterhead">
'+re.sub(r'^  ','',inner,flags=re.M)+'            </header>
'
a='            <section class="letter-body">
'
assert s.count(a)==1
s=s.replace(a,new+a,1)
open(p,'w').write(s)

p='css/style.css'
c=open(p).read()
def rep(a,b):
    global c
    assert c.count(a)==1,a
    c=c.replace(a,b,1)
rep("    aspect-ratio: 8.5 / 11;
    overflow: hidden;
","    aspect-ratio: 8.5 / 11;
    display: flex;
    flex-direction: column;
    overflow: hidden;
")
rep("section.letter-body {
    position: absolute;
    inset: 0;
    padding: 12cqw 9cqw 14cqw;
    overflow-y: auto;","section.letter-body {
    flex: 1;
    min-height: 0;
    padding: 0 9cqw 14cqw;
    overflow-y: auto;")
rep("header.letterhead {
    margin-bottom: 1.6em;
    text-align: center;
}","header.letterhead {
    padding: 12cqw 9cqw 1.6em;
    font-size: 0.9375rem;
    font-weight: 400;
    line-height: 1.5;
    text-align: center;
}

header.letterhead p {
    margin: 0;
}")
open(p,'w').write(c)
EOF
